func nice_quota(v: float) -> float:
	var lim: float = v / 20.0
	var step: float = 10.0
	if lim >= 10.0:
		var p: float = pow(10.0, floor(log(lim) / log(10.0) + 1e-9))
		step = 2.5 * p if 2.5 * p <= lim else p
	return maxf(step, round(v / step) * step)

private static List<String> allEntryIds(Minecraft client) {
    List<String> entries = new ArrayList<>();
    for (Item item : BuiltInRegistries.ITEM) {
        if (item == Items.AIR) continue;
        String id = BuiltInRegistries.ITEM.getKey(item).toString();
        entries.addAll(Variants.expand(id, client));
    }
    return entries;
}

public static void start(Minecraft client, long seed) {
    List<String> entries = allEntryIds(client);
    Collections.shuffle(entries, new Random(seed));

    data = new Data();
    data.seed = seed;
    data.order = entries;
    data.active = true;
    openCache = null;
    save();
}
